using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;

namespace CrossServiceAuth
{
    public class CertificateChainValidator
    {
        private readonly HashSet<string> _trustedRootThumbprints;
        private readonly Dictionary<string, DateTime> _revocationCache;
        private readonly TimeSpan _cacheExpiry = TimeSpan.FromMinutes(30);
        private readonly object _cacheLock = new object();

        public CertificateChainValidator(IEnumerable<string> trustedRootThumbprints)
        {
            _trustedRootThumbprints = new HashSet<string>(
                trustedRootThumbprints.Select(t => t.ToUpperInvariant()),
                StringComparer.OrdinalIgnoreCase);
            _revocationCache = new Dictionary<string, DateTime>();
        }

        public ValidationResult ValidateServiceCertificate(
            X509Certificate2 presentedCert,
            string expectedServiceName,
            X509Certificate2Collection intermediates = null)
        {
            if (presentedCert == null)
                return ValidationResult.Failure("No certificate presented");

            // Step 1: Check certificate temporal validity
            var now = DateTime.UtcNow;
            if (now < presentedCert.NotBefore || now > presentedCert.NotAfter)
                return ValidationResult.Failure("Certificate is not within validity period");

            // Step 2: Validate the subject alternative name matches expected service
            if (!ValidateServiceIdentity(presentedCert, expectedServiceName))
                return ValidationResult.Failure($"Certificate SAN does not match service '{expectedServiceName}'");

            // Step 3: Build and validate the certificate chain
            var chainResult = ValidateChain(presentedCert, intermediates);
            if (!chainResult.IsValid)
                return chainResult;

            // Step 4: Check key usage
            if (!ValidateKeyUsage(presentedCert))
                return ValidationResult.Failure("Certificate key usage is not appropriate for authentication");

            // Step 5: Check revocation status
            if (IsRevoked(presentedCert))
                return ValidationResult.Failure("Certificate has been revoked");

            return ValidationResult.Success();
        }

        private bool ValidateServiceIdentity(X509Certificate2 cert, string expectedServiceName)
        {
            var sanExtension = cert.Extensions
                .OfType<X509Extension>()
                .FirstOrDefault(e => e.Oid?.Value == "2.5.29.17");

            if (sanExtension == null)
            {
                // Fall back to CN matching if no SAN present
                var cn = ExtractCommonName(cert.Subject);
                return string.Equals(cn, expectedServiceName, StringComparison.OrdinalIgnoreCase);
            }

            var sanNames = ParseSubjectAlternativeNames(sanExtension.RawData);
            return sanNames.Any(san =>
                MatchesServiceName(san, expectedServiceName));
        }

        private bool MatchesServiceName(string sanEntry, string expectedName)
        {
            if (sanEntry.StartsWith("*."))
            {
                var sanDomain = sanEntry.Substring(2);
                var expectedParts = expectedName.Split('.');
                if (expectedParts.Length < 2) return false;
                var expectedDomain = string.Join(".", expectedParts.Skip(1));
                return string.Equals(sanDomain, expectedDomain, StringComparison.OrdinalIgnoreCase);
            }
            return string.Equals(sanEntry, expectedName, StringComparison.OrdinalIgnoreCase);
        }

        private ValidationResult ValidateChain(X509Certificate2 presentedCert, X509Certificate2Collection intermediates)
        {
            using (var chain = new X509Chain())
            {
                chain.ChainPolicy.RevocationMode = X509RevocationMode.NoCheck;
                chain.ChainPolicy.VerificationFlags = X509VerificationFlags.AllowUnknownCertificateAuthority;
                chain.ChainPolicy.UrlRetrievalTimeout = TimeSpan.FromSeconds(5);

                if (intermediates != null)
                {
                    chain.ChainPolicy.ExtraStore.AddRange(intermediates);
                }

                bool chainBuilt = chain.Build(presentedCert);

                if (!chainBuilt)
                {
                    var errors = chain.ChainStatus
                        .Where(s => s.Status != X509ChainStatusFlags.UntrustedRoot)
                        .Select(s => s.StatusInformation);

                    if (errors.Any())
                        return ValidationResult.Failure($"Chain validation failed: {string.Join("; ", errors)}");
                }

                // Verify the root is in our trusted set
                var rootCert = chain.ChainElements[chain.ChainElements.Count - 1].Certificate;
                var rootThumbprint = rootCert.Thumbprint;

                if (!_trustedRootThumbprints.Contains(rootThumbprint))
                {
                    // Check if any element in the chain is directly trusted
                    bool anyTrusted = chain.ChainElements
                        .Cast<X509ChainElement>()
                        .Any(elem => _trustedRootThumbprints.Contains(elem.Certificate.Thumbprint));

                    if (!anyTrusted)
                        return ValidationResult.Failure("Certificate chain does not terminate at a trusted root");
                }

                return ValidationResult.Success();
            }
        }

        private bool ValidateKeyUsage(X509Certificate2 cert)
        {
            var ekuExtension = cert.Extensions
                .OfType<X509EnhancedKeyUsageExtension>()
                .FirstOrDefault();

            if (ekuExtension == null)
                return true; // No EKU means all usages permitted

            var serverAuthOid = "1.3.6.1.5.5.7.3.1";
            var clientAuthOid = "1.3.6.1.5.5.7.3.2";

            return ekuExtension.EnhancedKeyUsages
                .Cast<Oid>()
                .Any(oid => oid.Value == serverAuthOid || oid.Value == clientAuthOid);
        }

        private bool IsRevoked(X509Certificate2 cert)
        {
            lock (_cacheLock)
            {
                if (_revocationCache.TryGetValue(cert.SerialNumber, out var revokedAt))
                    return revokedAt <= DateTime.UtcNow;
            }
            return false;
        }

        public void AddRevocation(string serialNumber, DateTime revokedAt)
        {
            lock (_cacheLock)
            {
                _revocationCache[serialNumber] = revokedAt;
            }
        }

        private string ExtractCommonName(string subject)
        {
            var parts = subject.Split(',');
            var cnPart = parts.FirstOrDefault(p => p.Trim().StartsWith("CN=", StringComparison.OrdinalIgnoreCase));
            return cnPart?.Trim().Substring(3)?.Trim();
        }

        private IEnumerable<string> ParseSubjectAlternativeNames(byte[] rawData)
        {
            var names = new List<string>();
            try
            {
                var asnData = new AsnEncodedData("2.5.29.17", rawData);
                var formatted = asnData.Format(true);
                var lines = formatted.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                foreach (var line in lines)
                {
                    var trimmed = line.Trim();
                    if (trimmed.StartsWith("DNS Name=", StringComparison.OrdinalIgnoreCase))
                        names.Add(trimmed.Substring(9));
                    else if (trimmed.StartsWith("DNS:", StringComparison.OrdinalIgnoreCase))
                        names.Add(trimmed.Substring(4));
                }
            }
            catch { }
            return names;
        }
    }

    public class ValidationResult
    {
        public bool IsValid { get; private set; }
        public string ErrorMessage { get; private set; }

        public static ValidationResult Success() => new ValidationResult { IsValid = true };
        public static ValidationResult Failure(string message) => new ValidationResult { IsValid = false, ErrorMessage = message };
    }
}
